<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount} from 'vue';import type {EditorController} from '../controller.ts';import type {Crop} from '../../../../packages/core/src/crop.ts';import {cropPixels} from '../../../../packages/core/src/crop.ts';import {sourceTimeAt} from '../../../../packages/core/src/animation.ts';import {atFrame} from '../controller.ts';import {toNumber} from '../../../../packages/core/src/time.ts';
const props=defineProps<{c:EditorController;open:boolean}>(),emit=defineEmits<{'update:open':[boolean]}>();
const crop=ref<Crop>({x:0,y:0,width:1,height:1}),ratio=ref('free'),stage=ref<HTMLElement>(),video=ref<HTMLVideoElement>();
const selected=computed(()=>props.c.selected.value),asset=computed(()=>selected.value?.asset),source=computed(()=>asset.value?props.c.api.url('/media/'+asset.value.id):''),pixels=computed(()=>asset.value?cropPixels(asset.value,crop.value):null);
const sourceAspect=computed(()=>(asset.value?.width||16)/(asset.value?.height||9));
let drag:{pointer:number;mode:string;x:number;y:number;before:Crop}|undefined;
watch(()=>props.open,open=>{if(open){crop.value={x:0,y:0,width:1,height:1,...selected.value?.clip.crop};ratio.value='free';props.c.playing.value=false;}else{video.value?.pause();drag=undefined;}});
function loaded(){if(video.value&&selected.value&&props.c.doc.value){const at=sourceTimeAt(selected.value.clip,atFrame(props.c.playhead.value,props.c.doc.value.fps));video.value.currentTime=Math.max(0,Math.min(toNumber(at)+.000001,(video.value.duration||1)-.0001));}}
const targetRatio=()=>ratio.value==='free'?undefined:ratio.value==='original'?1:ratio.value.split(':').map(Number).reduce((a,b)=>a/b)/sourceAspect.value;
function selectRatio(){const r=targetRatio();if(!r)return;const c=crop.value;let w=c.width,h=c.height;if(w/h>r)w=h*r;else h=w/r;crop.value={x:c.x+(c.width-w)/2,y:c.y+(c.height-h)/2,width:w,height:h};}
function begin(event:PointerEvent){if(event.button!==0||!stage.value)return;const target=event.target as HTMLElement,handle=target.closest<HTMLElement>('[data-crop-handle]');if(!handle&&!target.closest('.crop-box'))return;event.preventDefault();stage.value.setPointerCapture(event.pointerId);drag={pointer:event.pointerId,mode:handle?.dataset.cropHandle||'move',x:event.clientX,y:event.clientY,before:{...crop.value}};}
function move(event:PointerEvent){if(!drag||event.pointerId!==drag.pointer||!stage.value)return;const box=stage.value.getBoundingClientRect(),dx=(event.clientX-drag.x)/box.width,dy=(event.clientY-drag.y)/box.height,c=drag.before;
 if(drag.mode==='move'){crop.value={...c,x:Math.max(0,Math.min(1-c.width,c.x+dx)),y:Math.max(0,Math.min(1-c.height,c.y+dy))};return;}
 const west=drag.mode.includes('w'),north=drag.mode.includes('n'),anchorX=west?c.x+c.width:c.x,anchorY=north?c.y+c.height:c.y;
 let w=Math.max(.01,Math.min(west?anchorX:1-anchorX,c.width+(west?-dx:dx))),h=Math.max(.01,Math.min(north?anchorY:1-anchorY,c.height+(north?-dy:dy)));const r=targetRatio();
 if(r){h=w/r;if(h>(north?anchorY:1-anchorY)){h=north?anchorY:1-anchorY;w=h*r;}}
 crop.value={x:west?anchorX-w:anchorX,y:north?anchorY-h:anchorY,width:w,height:h};
}
function finish(){drag=undefined;}
function number(key:keyof Crop,value:number){const c={...crop.value,[key]:value/100};c.width=Math.max(.01,Math.min(1,c.width));c.height=Math.max(.01,Math.min(1,c.height));c.x=Math.max(0,Math.min(1-c.width,c.x));c.y=Math.max(0,Math.min(1-c.height,c.y));crop.value=c;selectRatio();}
async function apply(){if(!selected.value)return;await props.c.guard(()=>props.c.edit({type:'clip.update',clipId:selected.value!.clip.id,changes:{crop:{...crop.value}}}));if(!props.c.error.value)emit('update:open',false);}
onBeforeUnmount(()=>{video.value?.pause();drag=undefined;});
</script>
<template><a-modal :open="open" title="裁剪比例" :width="850" :get-container="false" :mask-closable="false" @update:open="emit('update:open',$event)"><template v-if="open&&asset">
 <div class="crop-viewport"><div ref="stage" class="crop-canvas" :style="{aspectRatio:String(sourceAspect),width:'min(100%, '+(360*sourceAspect)+'px)'}" @pointerdown="begin" @pointermove="move" @pointerup="finish" @pointercancel="finish" @lostpointercapture="finish"><img v-if="asset.kind==='image'" :src="source" alt="裁剪源画面" draggable="false" /><video v-else ref="video" :src="source" muted playsinline preload="auto" @loadedmetadata="loaded" /><div class="crop-box" :style="{left:crop.x*100+'%',top:crop.y*100+'%',width:crop.width*100+'%',height:crop.height*100+'%'}" aria-label="画面裁剪框"><i class="third-v first"></i><i class="third-v second"></i><i class="third-h first"></i><i class="third-h second"></i><span v-for="corner in ['nw','ne','sw','se']" :key="corner" :data-crop-handle="corner" :class="['crop-corner',corner]"></span></div></div></div>
 <div class="crop-options"><label>裁剪比例<select v-model="ratio" aria-label="画面裁剪比例" @change="selectRatio"><option value="free">自由</option><option value="original">原始比例</option><option v-for="r in ['16:9','9:16','1:1','4:3','3:4','2.35:1']" :key="r" :value="r">{{r}}</option></select></label><label v-for="[key,label] in [['x','左侧'],['y','顶部'],['width','宽度'],['height','高度']]" :key="key">{{label}}<a-input-number :value="Number((crop[key as keyof Crop]*100).toFixed(2))" :aria-label="'裁剪'+label+'百分比'" :min="key==='x'||key==='y'?0:1" :max="100" :step="1" :precision="2" @change="(v:any)=>number(key as keyof Crop,Number(v))" />%</label></div><p class="quiet">拖动画面框调整范围；拖动四角改变大小。{{pixels?.width}} × {{pixels?.height}} 像素，确认后适配工程画布。</p>
 </template><template #footer><a-button aria-label="恢复完整画面" @click="crop={x:0,y:0,width:1,height:1};ratio='free'">恢复原图</a-button><a-button @click="emit('update:open',false)">取消</a-button><a-button type="primary" :disabled="c.busy.value||c.readOnly.value" @click="apply">确认裁剪</a-button></template></a-modal></template>
